section.para:
Pass one of the AI_MATKEY_XXX constants for the last three parameters (the example reads the AI_MATKEY_SHININESS_STRENGTH property of the first diffuse texture) float specStrength = 1.f; // default value, remains unmodified if we fail.
aiGetMaterialFloat(mat, AI_MATKEY_SHININESS_STRENGTH,
   (float*)&specStrength);

Pass one of the AI_MATKEY_XXX constants for the last three parameters (the example reads the AI_MATKEY_UVTRANSFORM property of the first diffuse texture) aiUVTransform trafo;
unsigned int max = sizeof(aiUVTransform);
if (AI_SUCCESS != aiGetMaterialFloatArray(mat, AI_MATKEY_UVTRANSFORM(aiTextureType_DIFFUSE,0),
   (float*)&trafo, &max) || sizeof(aiUVTransform) != max)
{
  // error handling
}
